#pragma once

// Spectral band replication (ISO/IEC 14496-3 §4.6.18), the tool HE-AAC
// wraps round an AAC-LC core: the core's upper band is made again from
// its lower one — the core signal analysed into 32 QMF bands, the high
// bands generated by patching the low ones through a chirped linear
// predictor, their envelope, noise floor and sinusoids set from what the
// stream sent, and the 64 bands synthesized at twice the core rate. One
// decoder per channel element (a single channel or a pair), reading the
// element's SBR payload each frame.
//
// Parametric stereo (HE-AAC v2) is owed: its payload is read past, and
// the one channel plays as two.

#include "media/SbrData.h"

#include <array>
#include <complex>
#include <cstdint>
#include <memory>
#include <span>
#include <vector>

namespace sashfold::media {

class SbrBits; // the AAC decoder's bit reader, handed in

class SbrDecoder {
public:
    // `core_rate`: the AAC core's sampling rate; the output is at twice it,
    // or at the core's own through the downsampled bank when the stream
    // says its SBR output rate is the core's.
    SbrDecoder(int core_rate, bool channel_pair, bool downsampled = false);
    ~SbrDecoder();
    SbrDecoder(SbrDecoder const&) = delete;
    SbrDecoder& operator=(SbrDecoder const&) = delete;

    // Reads one frame's sbr_extension_data from the bits of a FIL element
    // (positioned after the extension type), `bit_count` bits long. False
    // when it could not be read; the frame then plays with the last header
    // and no new data (the high band is kept quiet).
    bool read(SbrBits& bits, std::size_t bit_count, bool crc);

    // Whether a header has been seen: until then the frames pass through
    // upsampled with no high band.
    bool ready() const;

    // One frame: each channel's 1024 core samples in, 2048 out at twice
    // the rate (1024 at the core's when downsampled). A pair's second channel is the first again until
    // parametric stereo is written.
    void process(float const* core_left, float const* core_right, float* out_left, float* out_right);

    void reset();

private:
    struct Impl;
    std::unique_ptr<Impl> m_impl;
};

// For the tests: the core signal through the 32-band analysis and the
// 64-band synthesis with nothing above the core's band — the signal at
// twice the rate, delayed by the banks, which is what the SBR tool does to
// the low band. `in` is a multiple of 1024 samples; `out` gets twice as many.
void sbr_qmf_round_trip(std::span<float const> in, std::vector<float>& out);

// A bit reader over a span, as the SBR payload is read bit by bit; the AAC
// decoder's own reader is wrapped into this.
class SbrBits {
public:
    explicit SbrBits(std::span<std::uint8_t const> data, std::size_t bit_position = 0)
        : m_data(data)
        , m_position(bit_position)
    {
    }
    std::uint32_t u(int n);
    bool flag() { return u(1) != 0; }
    void skip(std::size_t n) { m_position += n; }
    std::size_t position() const { return m_position; }
    bool failed() const { return m_failed; }

private:
    std::span<std::uint8_t const> m_data;
    std::size_t m_position;
    bool m_failed = false;
};

}
